package ro.leo.visual;
import ro.leo.i18n.L;import android.os.*;import android.net.Uri;import android.view.*;import android.webkit.*;import android.widget.*;import java.io.*;import org.json.*;
/** Isolated process and origin. No JS interface, remote resources, file/content access or permission grants. */
public final class WebRuntimeActivity extends LeoActivity {
 WebView web;String origin,id;File folder;
 protected void onCreate(Bundle b){super.onCreate(b);try{id=getIntent().getStringExtra("web_app");if(!WebAppPackages.validId(id))throw new IOException();folder=new File(WebAppPackages.base(WebRuntimeActivity.this),id);JSONObject manifest=WebAppPackages.manifest(folder);if(!id.equals(manifest.getString("id")))throw new IOException();WorkspaceSessions.recordWeb(WebRuntimeActivity.this,id);origin="https://"+id+".apps.leo.invalid";begin(manifest.getString("name"));web=new WebView(WebRuntimeActivity.this);web.setBackgroundColor(palette.background);WebSettings s=web.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setAllowFileAccessFromFileURLs(false);s.setAllowUniversalAccessFromFileURLs(false);s.setBlockNetworkLoads(true);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSavePassword(false);s.setGeolocationEnabled(false);ServiceWorkerController.getInstance().getServiceWorkerWebSettings().setBlockNetworkLoads(true);s.setSupportMultipleWindows(false);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,String u){return !allowed(u);}public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return !allowed(r.getUrl().toString());}public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){return resource(r.getUrl().toString());}public WebResourceResponse shouldInterceptRequest(WebView v,String u){return resource(u);}});web.setWebChromeClient(new WebChromeClient(){public void onPermissionRequest(PermissionRequest r){r.deny();}public boolean onShowFileChooser(WebView w,ValueCallback<Uri[]> result,FileChooserParams p){result.onReceiveValue(null);return true;}});web.setDownloadListener(new DownloadListener(){public void onDownloadStart(String u,String a,String d,String m,long l){notice(L.t("Descărcare indisponibilă"));}});root.addView(web,new LinearLayout.LayoutParams(-1,0,1));left=new Runnable(){public void run(){options(L.t("Aplicație web"),new String[]{L.t("Reîncarcă"),L.t("Șterge datele aplicației"),L.t("Închide")},new Choice(){public void pick(final int n){if(n==0)web.reload();else if(n==1)options(L.t("Ștergi datele locale?"),new String[]{L.t("Păstrează"),L.t("Șterge")},new Choice(){public void pick(final int yes){if(yes==1){web.evaluateJavascript("localStorage.clear();sessionStorage.clear();location.reload()",null);}}});else finish();}});}};back=new Runnable(){public void run(){finish();}};footer(L.t("Opțiuni"),L.t("Selectează"),L.t("Înapoi"));web.loadUrl(origin+"/"+manifest.getString("entry"));web.requestFocus();}catch(Throwable e){begin(L.t("Runtime web indisponibil"));root.addView(text(L.t("Motorul web nu a putut porni. Aplicațiile native Leo rămân disponibile."),17));footer("","",L.t("Înapoi"));}}
 boolean allowed(String value){try{Uri u=Uri.parse(value);return "https".equals(u.getScheme())&&(id+".apps.leo.invalid").equals(u.getHost())&&u.getPort()==-1&&u.getUserInfo()==null;}catch(Exception e){return false;}}
 WebResourceResponse resource(String url){try{if(!allowed(url))throw new IOException();String path=Uri.parse(url).getPath();if(path==null||!path.startsWith("/")||!WebAppPackages.safePath(path.substring(1)))throw new IOException();File f=new File(folder,path.substring(1));if(!LeoFileProvider.inside(folder,f)||!f.isFile()||f.length()>524288)throw new IOException();String mime=path.endsWith(".html")?"text/html":path.endsWith(".js")?"application/javascript":path.endsWith(".css")?"text/css":path.endsWith(".png")?"image/png":path.endsWith(".svg")?"image/svg+xml":"application/octet-stream";java.util.Map<String,String> headers=new java.util.HashMap<String,String>();headers.put("Content-Security-Policy","default-src 'self' data:; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; connect-src 'none'; object-src 'none'; frame-src 'none'; child-src 'none'; form-action 'none'; base-uri 'none'");headers.put("X-Content-Type-Options","nosniff");return new WebResourceResponse(mime,"UTF-8",200,"OK",headers,new FileInputStream(f));}catch(Exception e){return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}}
 public boolean dispatchKeyEvent(KeyEvent e){if(web!=null&&(e.getKeyCode()>=KeyEvent.KEYCODE_DPAD_UP&&e.getKeyCode()<=KeyEvent.KEYCODE_DPAD_CENTER)){if(e.getAction()==KeyEvent.ACTION_DOWN){int key=e.getKeyCode();web.evaluateJavascript("window.leoKey && window.leoKey("+key+")",null);}return true;}return super.dispatchKeyEvent(e);}
 protected void onPause(){if(web!=null)web.onPause();super.onPause();}protected void onResume(){super.onResume();if(web!=null)web.onResume();}protected void onDestroy(){if(web!=null){web.stopLoading();web.destroy();}super.onDestroy();}
}
